mapper.update:
UPDATE comment
SET content = #{content}, modify_date = NOW()
WHERE id = #{commentId};

mapper.select:
SELECT id AS comment_id, house_info_id, member_uuid, nickname, content, regist_date, modify_date
FROM comment
WHERE id = #{id};


SELECT id AS comment_id, house_info_id, member_uuid, nickname, content, regist_date, modify_date
FROM comment
WHERE is_deleted = false
ORDER BY regist_date DESC
LIMIT #{limitPlusOne}
OFFSET #{offset};

mapper.delete:
UPDATE comment
SET is_deleted = true
WHERE id = #{commentId};
